                            participants: {
                                diverId: string;
                                /** @description The Diver's name, as every User sees it */
                                name: string;
                                /**
                                 * @description buddy: dived together; guide: led the dive; instructor: taught on it
                                 * @enum {unknown}
                                 */
                                role: "buddy" | "guide" | "instructor";
                            }[];
